// Справочник SQL: подключение к серверам баз данных и управление ими.
// MySQL и MariaDB (синтаксис почти одинаковый, отличия отмечены), PostgreSQL, общий SQL.
// Во всех примерах — нейтральные имена (shop, orders, app_user, 192.168.1.20); в шаблонах — параметры {{…}}.
import type { CommandInput, RiskLevel } from '../src/shared/types';
import { classifyCommand } from '../src/shared/risk';

type Db = 'sql' | 'mysql' | 'postgresql';

interface SqlDef {
  id: string;
  db: Db;
  cat: string;
  title: string;
  /** Пример команды с нейтральными значениями. */
  cmd: string;
  desc: string;
  /** Шаблон с параметрами {{DATABASE}}, {{TABLE}}, {{USERNAME}}… */
  tpl?: string;
  /** Команда оболочки Linux (а не оператор внутри клиента mysql/psql). */
  sh?: boolean;
  ex?: [string, string][];
  warn?: string[];
  out?: string;
  /** Отличия между СУБД и версиями. */
  diff?: string;
  priv?: string;
  rel?: string[];
  docs?: string;
  tags?: string[];
  basic?: boolean;
  risk?: RiskLevel;
  pkg?: string;
}

const LABEL: Record<Db, string> = { sql: 'Общий SQL', mysql: 'MySQL / MariaDB', postgresql: 'PostgreSQL' };
const TAGS: Record<Db, string[]> = {
  sql: ['sql', 'база данных', 'бд', 'mysql', 'mariadb', 'postgresql'],
  mysql: ['sql', 'база данных', 'бд', 'mysql', 'mariadb', 'мускул', 'мария'],
  postgresql: ['sql', 'база данных', 'бд', 'postgresql', 'postgres', 'постгрес', 'psql']
};
const WHERE: Record<Db, string> = {
  sql: 'Внутри клиента базы данных: mysql (приглашение mysql> или MariaDB [(none)]>) или psql (приглашение имя_базы=#). Оператор заканчивается точкой с запятой.',
  mysql: 'Внутри клиента mysql / mariadb (приглашение mysql> или MariaDB [(none)]>). Оператор заканчивается точкой с запятой.',
  postgresql: 'Внутри клиента psql (приглашение имя_базы=# или =>). SQL-оператор заканчивается точкой с запятой; служебные команды psql начинаются с «\\» и точка с запятой им не нужна.'
};
const COMPAT: Record<Db, string> = {
  sql: 'MySQL 5.7/8.x, MariaDB 10.x/11.x, PostgreSQL 12+',
  mysql: 'MySQL 5.7/8.x, MariaDB 10.x/11.x',
  postgresql: 'PostgreSQL 12+'
};

function Q(d: SqlDef): CommandInput {
  const auto = classifyCommand(d.cmd, 'sql').level;
  return {
    uid: `builtin:sql:${d.id}`,
    kind: 'sql',
    entryType: d.cmd.includes('\n') ? 'sequence' : 'command',
    platform: d.db,
    vendorLabel: LABEL[d.db],
    os: d.sh ? 'Linux (Debian / Ubuntu)' : '',
    category: d.cat,
    title: d.title,
    command: d.cmd,
    description: d.desc,
    details: {
      syntax: d.sh ? 'В терминале Linux (bash) на сервере с базой данных.' : WHERE[d.db],
      examples: d.ex?.map(([cmd, desc]) => ({ cmd, desc })),
      output: d.out,
      privileges: d.priv ?? (d.sh ? 'обычно root (sudo) или системный пользователь СУБД' : 'пользователь базы с правами на объект'),
      compat: COMPAT[d.db],
      package: d.pkg,
      preinstalled: !d.pkg,
      warnings: d.warn,
      related: d.rel,
      docs: d.docs,
      versionNotes: d.diff
    },
    template: d.tpl ?? null,
    risk: d.risk ?? auto,
    riskManual: false,
    mode: d.sh ? 'shell' : 'any',
    source: 'builtin',
    verified: false,
    needsReview: false,
    vendorUnknown: false,
    sensitive: false,
    favorite: false,
    userModified: false,
    tags: [...TAGS[d.db], ...(d.tags ?? []), ...(d.basic ? ['основы'] : [])]
  };
}

